#include <iostream>
#include <string>
#include <vector>
#include <sstream>

std::string convertMarkdownToHtml(const std::string& markdown) {
    std::vector<std::string> lines;
    std::istringstream iss(markdown);
    std::string line;
    while (std::getline(iss, line, '\n')) {
        lines.push_back(line);
    }
    std::ostringstream oss;
    for (const auto& line : lines) {
        oss << "<p>" << line << "</p>\n";
    }
    return oss.str();
}

int main() {
    std::string markdown = "This is a markdown formatted text.\nThis is a second line of markdown text.\n";
    std::string html = convertMarkdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
